"""Launch the real Volcan app in durable mode against in-memory AWS fakes.

Usage: python tests/fixtures/durable_server.py <port>

The composition root reads VOLCAN_STATE_TABLE and VOLCAN_APPROVAL_SECRET_ARN at
import time and asks boto3 for a DynamoDB table and a Secrets Manager secret.
This launcher replaces boto3's constructors with tests/fixtures/fake_dynamodb.py
first, so the whole app (routes, middleware, MCP transport and page) runs the
durable code path with no AWS call. The fake secret's value arrives in
VOLCAN_FAKE_SECRET_STRING, generated by the test at run time, and is removed
from the environment before the app is imported.
"""
import os
import sys

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, REPO_ROOT)


def main(port: int) -> None:
    from tests.fixtures.fake_dynamodb import FakeSecretsManager, FakeTable, install_fake_aws

    table_name = os.environ["VOLCAN_STATE_TABLE"]
    secret_arn = os.environ["VOLCAN_APPROVAL_SECRET_ARN"]
    secret_string = os.environ.pop("VOLCAN_FAKE_SECRET_STRING")
    install_fake_aws(FakeTable(), FakeSecretsManager(secret_arn, secret_string), table_name)

    import uvicorn

    from src.interfaces.mcp_server import app

    uvicorn.run(app, host="127.0.0.1", port=port, log_level="warning")


if __name__ == "__main__":
    main(int(sys.argv[1]))
